#include <vector>
#include <algorithm>
#include <cmath>
using namespace std;

class Solution {
public:
    long long minMoves(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        int median = nums[nums.size() / 2];
        long long moves = 0;
        for (int x : nums) {
            moves += abs(x - median);
        }
        return moves;
    }
};

import java.util.*;

class Solution {
    public long minMoves(int[] nums) {
        Arrays.sort(nums);
        int median = nums[nums.length / 2];
        long moves = 0;
        for (int x : nums) {
            moves += Math.abs((long)x - median);
        }
        return moves;
    }
}

var minMoves = function(nums) {
    nums.sort((a, b) => a - b);
    const median = nums[Math.floor(nums.length / 2)];
    let moves = 0n;
    for (const x of nums) {
        moves += BigInt(Math.abs(x - median));
    }
    return Number(moves);
};
